<!--
  LanguageList — 自绘语言分布：每行一个（图标 + 语言名 + 进度条 + 百分比），antfu 极简风、无边框。
  数据来自 src/data/languages.json（构建时由 scripts/fetch-langs.mjs 抓取 GitHub Languages API 生成）。
-->
<script setup lang="ts">
import languages from '../data/languages.json'

// GitHub API 语言名 → 彩色品牌图标（i-logos-* 多彩 logo；无 logos 的回退 simple-icons）
const iconMap: Record<string, string> = {
  'Rust': 'i-logos-rust',
  'JavaScript': 'i-logos-javascript',
  'JavaScript': 'i-logos-javascript',
  'TypeScript': 'i-logos-typescript-icon',
  'C': 'i-logos-c',
  'Vue': 'i-logos-vue',
  'C++': 'i-logos-c-plusplus',
  'Python': 'i-logos-python',
  'CSS': 'i-logos-css-3',
  'HTML': 'i-logos-html-5',
  'C#': 'i-logos-c-sharp',
  'Go': 'i-logos-go',
  'Lua': 'i-logos-lua',
  'SCSS': 'i-logos-sass',
  'Dockerfile': 'i-logos-docker-icon',
  'Shell': 'i-logos-bash-icon',
  'PowerShell': 'i-simple-icons-powershell',
  'AutoHotkey': 'i-simple-icons-autohotkey',
  'Other': 'i-ri-more-2-fill',
}

// 进度条填充色（品牌色；未知/Other 用灰）
const colorMap: Record<string, string> = {
  'Rust': '#CE422B',
  'JavaScript': '#F0DB4F',
  'TypeScript': '#3178C6',
  'C': '#A8B9CC',
  'Vue': '#42B883',
  'C++': '#00599C',
  'Python': '#3776AB',
  'CSS': '#663399',
  'HTML': '#E34F26',
  'C#': '#512BD4',
  'Go': '#00ADD8',
  'Lua': '#2C2D72',
  'PowerShell': '#5391FE',
  'SCSS': '#CC6699',
  'Dockerfile': '#2496ED',
  'Shell': '#4EAA25',
}

// 只展示占比 >= 1.5% 的语言（含 CSS 在内的小项不单独显示），其余合并为 "Other"
const items = (() => {
  const shown = languages.filter(l => l.percent >= 1.5)
  const rest = languages.filter(l => l.percent < 1.5)
  if (rest.length) {
    shown.push({
      name: 'Other',
      bytes: rest.reduce((a, b) => a + b.bytes, 0),
      percent: Math.round(rest.reduce((a, b) => a + b.percent, 0) * 10) / 10,
    })
  }
  return shown
})()
</script>

<template>
  <div class="max-w-xl space-y-1.5 text-sm">
    <div
      v-for="l in items"
      :key="l.name"
      class="flex items-center gap-3"
    >
      <span
        v-if="iconMap[l.name]"
        class="shrink-0"
        :class="iconMap[l.name]"
        :style="iconMap[l.name].startsWith('i-simple') ? { color: colorMap[l.name] } : undefined"
      />
      <span class="w-24 shrink-0 text-left">{{ l.name }}</span>
      <div class="h-1.5 flex-1 overflow-hidden rounded-full bg-[#8882]">
        <div
          class="h-full rounded-full"
          :style="{ width: `${l.percent}%`, background: colorMap[l.name] || '#888' }"
        />
      </div>
      <span class="w-12 shrink-0 text-right opacity-60 tabular-nums">{{ l.percent }}%</span>
    </div>
  </div>
</template>

